import sys
import os
import numpy as np
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
from scipy.stats import gaussian_kde
from sklearn.utils import resample
from scipy.signal import find_peaks

ROOT = "/Results/AllSpecies/Paranome/WGD_Paranome"
os.chdir(ROOT)

# Sample data: Replace this with your actual Ks data
ks_data = pd.read_csv("data/P_scoparium_genome_Helixer.functions.IPScan.AA50.nonTE.cds.fa.tsv.ks.tsv", sep="\t")

sps = "Porophyllum scoparium"

# ks_data = data[data["Species"] == sps]

# Process and filter ks data generated by wgd ksd
ks_data = ks_data.groupby(['family', 'node'])['dS'].mean().reset_index()
print(ks_data.head())
ks_data = ks_data[ks_data["dS"].between(0.001, 2)]


ks_data.to_csv("/Results/AllSpecies/Paranome/WGD_Paranome/new_results3_filter2/" + sps.replace(" ", "_") + str('.Ks_data.tsv'), sep="\t", index=False)

# print(min(ks_data["dS"]), max(ks_data["dS"]), ks_data.shape[0])

f = open("/Results/AllSpecies/Paranome/WGD_Paranome/new_results3_filter2/" + sps.replace(" ", "_") + str('.Ks.BS.KDE.log'), 'w')
# print(sps + " Minimum Ks: " + str(min(ks_data["dS"])) + " Maximum Ks: " + str(max(ks_data["dS"])) + " Number of pairs: " + str(ks_data.shape[0]), file=f)

ks_data = ks_data["dS"] #- 0.04  # This subtraction only used for Hannuus to bring the peak from 0.53 - 0.48


# Function to compute KDE peaks
def compute_kde_peaks(data, x_grid):
    kde = gaussian_kde(data)
    kde_values = kde(x_grid)
    peaks, _ = find_peaks(kde_values)
    return x_grid[peaks]


# Generate x-axis grid
x_grid = np.linspace(min(ks_data), max(ks_data), 1000)

# Original peaks
original_peaks = compute_kde_peaks(ks_data, x_grid)

# Bootstrap resampling to get CI
num_resamples = 1000
bootstrap_peaks = np.zeros((num_resamples, len(original_peaks)))

for i in range(num_resamples):
    resample_data = resample(ks_data, n_samples=round(ks_data.size/2))
    resample_peaks = compute_kde_peaks(resample_data, x_grid)
    for j, peak in enumerate(original_peaks):
        if len(resample_peaks) > 0:
            nearest_peak = resample_peaks[np.argmin(np.abs(resample_peaks - peak))]
            bootstrap_peaks[i, j] = nearest_peak

# Calculate 90% CI for peaks
peak_conf_intervals = np.percentile(bootstrap_peaks, [5, 95], axis=0)

# Plotting histogram, KDE with peaks and 90% CI
plt.figure(figsize=(5, 3))
plt.rcParams.update({'font.size': 8})

# Plot histogram
# plt.hist(ks_data, bins=100, density=True, alpha=0.5, color='gray', label='$K_s$ data')

# Plot KDE
kde = gaussian_kde(ks_data)
kde_values = kde(x_grid)
plt.plot(x_grid, kde_values, label='KDE', color='blue')

# colors = ["red", "green", "purple"]
# Plot peaks and confidence intervals
for i, peak in enumerate(original_peaks):
    # if i > 1:
    #     break
    # if i == 1:
    #     plt.axvline(peak, color="red", linestyle='--', label=f'Peak {i+1}: {round(peak, 2)}')
    #     plt.axvspan(peak_conf_intervals[0, i], peak_conf_intervals[1, i], color='lightblue', alpha=0.5)#, label=f'90% CI for Peak {i+1}')
    plt.axvline(peak, color="red", linestyle='--', label=f'Peak {i+1}: {round(peak, 2)}')
    plt.axvspan(peak_conf_intervals[0, i], peak_conf_intervals[1, i], color='lightblue', alpha=0.5)#, label=f'90% CI for Peak {i+1}')


# Add labels and legend
plt.xlabel('$K_s$ values')
plt.ylabel('Density')
plt.title(sps, fontstyle='italic', fontsize=10)
plt.legend()
# plt.legend(bbox_to_anchor = (1.3, 0.6), loc='center right')
plt.xlim(left=0.0, right=2.01)
plt.ylim(bottom=0.0)
plt.tight_layout()

# Display the plot
plt.savefig("/Results/AllSpecies/Paranome/WGD_Paranome/new_results3_filter2/"+sps.replace(" ", "_")+".Ks.BS.KDE.pdf", dpi=150)
plt.savefig("/Results/AllSpecies/Paranome/WGD_Paranome/new_results3_filter2/"+sps.replace(" ", "_")+".Ks.BS.KDE.png")
# plt.show()

# Check if original peaks fall within the 90% CI
for i, peak in enumerate(original_peaks):
    if peak >= peak_conf_intervals[0, i] and peak <= peak_conf_intervals[1, i]:
        print(sps, f"Peak {i+1} {'%.2f'%(peak)} is within the 90% CI range: {'%.2f'%(peak_conf_intervals[0, i])}, {'%.2f'%(peak_conf_intervals[1, i])}")
        print(sps, f"Peak {i+1} {'%.2f'%(peak)} is within the 90% CI range: {'%.2f'%(peak_conf_intervals[0, i])}, {'%.2f'%(peak_conf_intervals[1, i])}", file=f)
    else:
        print(sps, f"Peak {i+1} {'%.2f'%(peak)} is NOT within the 90% CI range: {'%.2f'%(peak_conf_intervals[0, i])}, {'%.2f'%(peak_conf_intervals[1, i])}")
        print(sps, f"Peak {i+1} {'%.2f'%(peak)} is NOT within the 90% CI range: {'%.2f'%(peak_conf_intervals[0, i])}, {'%.2f'%(peak_conf_intervals[1, i])}", file=f)

sys.exit()